# First, let's get an overview of CONTEXT
print("CONTEXT size:", await CONTEXT.info())

# Search for key terms
sections = ["[grade]", "[grader tail]", "[facts]", "[first wrong step]", "[checkpoint]", "[request]", "[turn", "[tool", "[result"]
for s in sections:
    results = await CONTEXT.search(s)
    if results:
        print(f"\n--- {s}: {len(results)} matches ---")
        for r in results[:5]:
            print(f"  offset={r['offset']}: {r['snippet'][:120]}")
    else:
        print(f"\n--- {s}: no matches ---")
